<script>
(function(){
  var root=document.getElementById('shop');
  if(!root){return;}
  var WA='910000011111';
  var P=[
    {name:'Indigo block-print kurta',cat:'Kurtas',price:1499,sizes:['S','M','L','XL','XXL'],label:'S-XXL'},
    {name:'Mustard handloom kurta',cat:'Kurtas',price:1699,sizes:['S','M','L','XL'],label:'S-XL'},
    {name:'White chikankari kurta',cat:'Kurtas',price:2199,sizes:['XS','S','M','L','XL'],label:'XS-XL',isNew:true},
    {name:'Maheshwari cotton saree',cat:'Sarees',price:3499,sizes:['Free size'],label:'Free size'},
    {name:'Chanderi silk-cotton saree',cat:'Sarees',price:4999,sizes:['Free size'],label:'Free size'},
    {name:'Ikat handloom saree',cat:'Sarees',price:3999,sizes:['Free size'],label:'Free size',isNew:true},
    {name:'Khadi cotton shirt',cat:'Shirts',price:1299,sizes:['S','M','L','XL','XXL'],label:'S-XXL'},
    {name:'Linen-blend shirt',cat:'Shirts',price:1599,sizes:['M','L','XL','XXL'],label:'M-XXL',isNew:true},
    {name:'Ajrakh dupatta',cat:'Dupattas',price:899,sizes:['Free size'],label:'Free size'},
    {name:'Bandhani dupatta',cat:'Dupattas',price:1099,sizes:['Free size'],label:'Free size'}
  ];
  var state={cat:'All',size:'All',price:'All'};
  var elProducts=root.querySelector('#tl-products');
  var elNew=root.querySelector('#tl-new');
  var elCount=root.querySelector('#tl-count');
  var elSize=root.querySelector('#tl-size');
  var elPrice=root.querySelector('#tl-price');
  var chips=root.querySelectorAll('.tl-chip');

  function money(n){return '\u20B9'+String(n).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
  function el(tag,cls,text){var e=document.createElement(tag);if(cls){e.className=cls;}if(text!==undefined){e.textContent=text;}return e;}
  function priceOk(p){
    if(state.price==='low'){return p.price<1500;}
    if(state.price==='mid'){return p.price>=1500&&p.price<=2999;}
    if(state.price==='high'){return p.price>=3000;}
    return true;
  }
  function matches(p){
    if(state.cat!=='All'&&p.cat!==state.cat){return false;}
    if(state.size!=='All'&&p.sizes.indexOf(state.size)===-1){return false;}
    return priceOk(p);
  }
  function card(p,showNewBadge){
    var c=el('article','j2-card tl-card');
    var ph=el('div','tl-photo','Photo coming soon');
    ph.setAttribute('role','img');
    ph.setAttribute('aria-label','Photo of '+p.name+' coming soon');
    if(showNewBadge&&p.isNew){ph.appendChild(el('span','tl-badge','New'));}
    c.appendChild(ph);
    c.appendChild(el('p','tl-cat',p.cat));
    c.appendChild(el('h3','tl-name',p.name));
    c.appendChild(el('p','tl-price',money(p.price)));
    c.appendChild(el('p','tl-sizes','Sizes: '+p.label));
    var a=el('a','j2-btn','Order on WhatsApp');
    a.href='https://wa.me/'+WA+'?text='+encodeURIComponent('Hi Thread & Loom, I would like to order: '+p.name);
    a.target='_blank';
    a.rel='noopener';
    c.appendChild(a);
    return c;
  }
  function render(){
    var list=P.filter(matches);
    elProducts.textContent='';
    if(!list.length){
      var e=el('div','j2-card tl-empty');
      e.appendChild(el('p','', 'No products match these filters.'));
      elProducts.appendChild(e);
    }else{
      list.forEach(function(p){elProducts.appendChild(card(p,true));});
    }
    elCount.textContent='Showing '+list.length+' of '+P.length+' products';
  }
  function renderNew(){
    elNew.textContent='';
    P.filter(function(p){return p.isNew;}).forEach(function(p){elNew.appendChild(card(p,false));});
  }
  chips.forEach(function(b){
    b.addEventListener('click',function(){
      state.cat=b.getAttribute('data-cat');
      chips.forEach(function(x){x.setAttribute('aria-pressed',x===b?'true':'false');});
      render();
    });
  });
  elSize.addEventListener('change',function(){state.size=elSize.value;render();});
  elPrice.addEventListener('change',function(){state.price=elPrice.value;render();});
  root.querySelector('#tl-reset').addEventListener('click',function(){
    state={cat:'All',size:'All',price:'All'};
    elSize.value='All';elPrice.value='All';
    chips.forEach(function(x){x.setAttribute('aria-pressed',x.getAttribute('data-cat')==='All'?'true':'false');});
    render();
  });
  renderNew();
  render();
})();
</script>
